217	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
218	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
219	  if (chunk.type === 'text') return textChunkCount + 1;
220	
221	  if (textChunkCount > 0) {
222	    log.debug('stream', `received ${textChunkCount} text chunks`);
223	  }
224	
225	  if (chunk.type === 'tool_result') {
226	    log.debug('stream', 'tool_result chunk', {
227	      messageCount: chunk.clientMessages.length,
228	      types: chunk.clientMessages.map(m => m.type),
229	    });
230	    return 0;
231	  }
