273	function streamSegment(
274	  ws: WebSocket,
275	  session: ChatSession,
276	  state: StreamState,
277	  key: StateIndexKey,
278	  createEntry: EntryFactory,
279	  content: string
280	): void {
281	  const isNew = initSegment(session, state, key, createEntry);
282	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
283	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
284	  appendDelta(session, state[key]!, content);
