330	  for (const msg of clientMessages) {
331	    log.debug('stream', 'forwarding client message to frontend', {
332	      type: msg.type,
333	      index: 'index' in msg ? msg.index : undefined,
334	    });
335	    sendJson(ws, msg);
336	  }
337	}
