/** Resolves once `check` holds, or after five hundred milliseconds, so a suite can wait out a server's own view of a close. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Terminates every socket of the suite's own, waits until each server has seen them close, then stops the servers. */
export async function drainClientsAndServers(clients: WebSocket[], servers: Array<HalServer>): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the members every engine needs, so an optional one can be added, replaced or left out per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}

